* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto,
    "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--text);
  color: var(--surface);
  padding: 0.75rem 1rem;
  border-radius: 0 0 var(--radius-sm) 0;
  z-index: 100;
}
.skip-link:focus { left: 0; outline: 3px solid var(--focus); outline-offset: 2px; }

.page {
  max-width: 720px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

.page__header { margin-bottom: 2rem; }

.eyebrow {
  margin: 0 0 0.5rem;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
}

h1 {
  margin: 0 0 0.75rem;
  font-size: clamp(1.75rem, 2.5vw + 1rem, 2.25rem);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.lede {
  margin: 0;
  color: var(--muted);
  font-size: 1.0625rem;
  max-width: 56ch;
}

.quiz__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1.25rem;
}

.form-field { display: block; }

.field {
  margin: 0;
  padding: 1.5rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.field__legend {
  display: block;
  padding: 0;
  margin-bottom: 1rem;
}

.field__index {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 0.25rem;
}

.field__label {
  display: block;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text);
  line-height: 1.35;
}

.field__help {
  margin: -0.5rem 0 1rem;
  color: var(--muted);
  font-size: 0.9375rem;
}

.options {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.option {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.75rem 0.875rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  transition: border-color 120ms ease, background-color 120ms ease;
}

.option:hover { border-color: var(--border-strong); }

.option input[type="checkbox"] {
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  margin: 0.1875rem 0 0;
  accent-color: var(--accent);
  cursor: pointer;
}

.option label {
  flex: 1;
  cursor: pointer;
  font-size: 1rem;
  color: var(--text);
  user-select: none;
}

.option:has(input:checked) {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.option:focus-within {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.option input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 3px;
}

.quiz__actions {
  margin-top: 1.75rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.btn {
  font: inherit;
  font-weight: 600;
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  min-height: 44px;
  transition: background-color 120ms ease, color 120ms ease, border-color 120ms ease;
}

.btn--primary {
  background: var(--accent);
  color: #fff;
}
.btn--primary:hover { background: var(--accent-hover); }

.btn--ghost {
  background: transparent;
  color: var(--text);
  border-color: var(--border);
}
.btn--ghost:hover { border-color: var(--border-strong); }

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.quiz__status {
  margin: 1.25rem 0 0;
  padding: 0;
  font-size: 0.9375rem;
  color: var(--muted);
  min-height: 1.5em;
}

.quiz__status.is-success {
  padding: 0.875rem 1rem;
  background: var(--success-bg);
  color: var(--success-text);
  border: 1px solid var(--success-border);
  border-radius: var(--radius-sm);
}

.quiz__status.is-error {
  padding: 0.875rem 1rem;
  background: var(--error-bg);
  color: var(--error-text);
  border: 1px solid var(--error-border);
  border-radius: var(--radius-sm);
}

@media (forced-colors: active) {
  .field, .option, .btn { border: 1px solid CanvasText; }
  .btn--primary { background: ButtonFace; color: ButtonText; }
  .option:has(input:checked) { background: Highlight; color: HighlightText; }
}
