  const file = "file://" + path.resolve(__dirname, "index.html");
  await page.goto(file, { waitUntil: "load" });

  // Initial state
  let results = await new AxePuppeteer(page)
    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa", "best-practice"])
