  for (const v of results.violations) {
    console.log("-", v.id, "|", v.impact, "|", v.help);
    for (const n of v.nodes) console.log("   target:", n.target.join(" "), "\n   summary:", n.failureSummary);
  }

  // After submitting (live region populated)
  await page.click('input[name="q1"][value="rust"]');
  await page.click('button[type="submit"]');
  await new Promise((r) => setTimeout(r, 200));

  results = await new AxePuppeteer(page)
    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa", "best-practice"])
    .analyze();
  console.log("\n=== After submit ===");
  console.log("violations:", results.violations.length);
  for (const v of results.violations) {
    console.log("-", v.id, "|", v.impact, "|", v.help);
